1	//! The editable note form, hosted in-pane by the cockpit's `_viewer`.
2	//!
3	//! Sibling of [`crate::todo_form`] but trimmed to fit the note model:
4	//! one single-line title field and one multi-line body field, no enums, no
5	//! comments, no blockers. The `draw` takes a `Rect` so the viewer can place
6	//! it directly; `handle_key` returns a [`NoteFormAction`] so the host
7	//! decides whether to debounce a save or to close.
8	//!
9	//! Saves go through the MCP client: a creation round-trip with
10	//! `note_create` on first save, then `note_update` for every
11	//! subsequent flush. The form never reads or writes the `.panopt/note/`
12	//! projection itself.
13	//!
14	//! The viewer polls [`Self::refresh_from_daemon`] on its `REFRESH` cadence so
15	//! a concurrent edit (another agent's `note_update`, a CLI write)
16	//! reconciles into the open form: untouched fields are replayed from the
17	//! remote value; fields the user is mid-edit on hold their local text and the
18	//! message line flags the conflict. The [`Baseline`] is always advanced to
19	//! the remote value so the next [`Self::flush`] sends only the user's still-
20	//! pending changes. Mirrors `todo_form.rs`'s refresh wiring (todo #40).
21	
22	use std::time::Instant;
23	
24	use anyhow::{anyhow, Result};
25	use crossterm::event::{
26	    KeyCode, KeyEvent, KeyEventKind, KeyModifiers, MouseButton, MouseEvent, MouseEventKind,
27	};
28	use ratatui::layout::{Constraint, Layout, Rect};
29	use ratatui::style::{Color, Modifier, Style};
30	use ratatui::widgets::{Block, Paragraph};
31	use ratatui::Frame;
32	use serde_json::{json, Value};
33	use tui_textarea::{CursorMove, TextArea};
34	
35	use crate::mcpclient::Client;
36	use crate::todo_form::{
37	    body_input, field_border_color, highlight_line, paste_into, paste_into_single_line,
38	    select_to_column, selected_text, single_line_input, text_area,
39	};
40	
41	/// What [`NoteForm::handle_key`] is telling the host to do next.
42	///
43	/// The viewer uses `Dirty` to start a debounce window and flush a short time
44	/// later; `Close` is the user's request to leave the form (Ctrl-C).
45	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
46	pub enum NoteFormAction {
47	    /// Nothing changed that the host needs to act on.
48	    Idle,
49	    /// A field changed: the host should consider this a pending save.
50	    Dirty,
51	    /// The user asked to close the form.
52	    Close,
53	}
54	
55	/// Which note field currently has focus.
56	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
57	enum Field {
58	    Title,
59	    Tags,
60	    Body,
61	}
62	
63	/// Snapshot of the editable fields the daemon last reported, captured at load
64	/// time and after each successful save/refresh.
65	///
66	/// `flush` diffs the current field values against this baseline and sends
67	/// only the fields that actually changed - so an autosave that fires while
68	/// the user has only touched the title doesn't echo back the stale body and
69	/// clobber a concurrent edit. Mirrors `todo_form::Baseline`.
70	#[derive(Clone, Default)]
71	struct Baseline {
72	    title: String,
73	    body: String,
74	    tags: Vec<String>,
75	}
76	
77	/// The editable state of the note form.
78	pub struct NoteForm {
79	    /// The daemon MCP URL with `?ws=...&observer=1`.
80	    pub(crate) url: String,
81	    /// The note's id, or `None` until a new note is first saved.
82	    pub(crate) id: Option<u64>,
83	
84	    title: TextArea<'static>,
85	    body: TextArea<'static>,
