206	    /// Handle one key press. The returned [`NoteFormAction`] tells the
207	    /// host whether the form is dirty (start the debounce), idle, or asking
208	    /// to close.
209	    pub fn handle_key(&mut self, key: KeyEvent) -> NoteFormAction {
210	        if key.kind != KeyEventKind::Press {
211	            return NoteFormAction::Idle;
212	        }
213	        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
214	        let shift = key.modifiers.contains(KeyModifiers::SHIFT);
215	
216	        // Ctrl-Shift-C: copy the current selection. Body uses our
217	        // wrap-aware `self.selection`; single-line textareas (Title /
218	        // Tags) keep their own `selection_range()`. Handled ahead of
219	        // the Ctrl-C close arm so the shift modifier disambiguates the
220	        // two. See `TodoForm::handle_key` for the WezTerm ⌘C mapping.
221	        if ctrl && shift && matches!(key.code, KeyCode::Char('c') | KeyCode::Char('C')) {
222	            let focused = self.focus;
223	            let copied = match (focused, self.selection) {
224	                (Field::Body, Some((anchor, tip))) if anchor != tip => {
225	                    let text = selected_text(self.body.lines(), anchor, tip);
226	                    if !text.is_empty() {
227	                        let _ = crate::clip::copy_to_clipboard(&text);
228	                    }
229	                    true
230	                }
231	                _ => false,
232	            };
233	            if !copied {
234	                if let Some(area) = self.single_line_textarea_mut(focused) {
235	                    if let Some((anchor, tip)) = area.selection_range() {
236	                        if anchor != tip {
237	                            let text = selected_text(area.lines(), anchor, tip);
238	                            if !text.is_empty() {
239	                                let _ = crate::clip::copy_to_clipboard(&text);
240	                            }
241	                        }
242	                    }
243	                }
244	            }
245	            return NoteFormAction::Idle;
246	        }
247	
248	        // Any other key: the visible selection is stale; clear before
249	        // dispatching so the highlight goes away on the next render.
250	        self.selection = None;
251	
252	        match key.code {
253	            // Ctrl-C closes the form; q/x must remain typeable in the body.
254	            KeyCode::Char('c') if ctrl => NoteFormAction::Close,
255	            // Tab cycles focus: Title -> Tags -> Body -> Title. BackTab walks
256	            // the same cycle in reverse so Shift-Tab is the inverse of Tab.
257	            KeyCode::Tab => {
258	                self.focus = match self.focus {
259	                    Field::Title => Field::Tags,
260	                    Field::Tags => Field::Body,
261	                    Field::Body => Field::Title,
262	                };
263	                NoteFormAction::Idle
264	            }
265	            KeyCode::BackTab => {
266	                self.focus = match self.focus {
267	                    Field::Title => Field::Body,
268	                    Field::Tags => Field::Title,
269	                    Field::Body => Field::Tags,
270	                };
271	                NoteFormAction::Idle
272	            }
273	            _ => self.field_key(key),
274	        }
275	    }
276	
277	    fn field_key(&mut self, key: KeyEvent) -> NoteFormAction {
278	        let changed = match self.focus {
279	            Field::Title => single_line_input(&mut self.title, key),
280	            Field::Tags => single_line_input(&mut self.tags, key),
281	            Field::Body => body_input(&mut self.body, key, self.body_view_height),
282	        };
283	        if changed {
284	            self.mark_dirty();
285	            NoteFormAction::Dirty
286	        } else {
287	            NoteFormAction::Idle
288	        }
289	    }
