291	    /// Handle one mouse event in the Body field. Mirrors
292	    /// [`crate::todo_form::TodoForm::handle_mouse`]; see that for the full
293	    /// lifecycle (Down anchors a selection, Drag extends it, Up emits OSC 52,
294	    /// scroll wheel walks the cursor).
295	    pub fn handle_mouse(&mut self, m: MouseEvent) -> NoteFormAction {
296	        let body_area = self.body_area;
297	        match m.kind {
298	            MouseEventKind::Down(MouseButton::Left) => {
299	                if let Some(area) = body_area {
300	                    if let Some(pos) = self.body_logical_pos_at(area, m.row, m.column) {
301	                        self.focus = Field::Body;
302	                        self.body
303	                            .move_cursor(CursorMove::Jump(pos.0 as u16, pos.1 as u16));
304	                        self.selection = Some((pos, pos));
305	                        return NoteFormAction::Idle;
306	                    }
307	                }
308	                if let Some((field, inner)) = self.text_field_at(m.row, m.column) {
309	                    self.focus = field;
310	                    if let Some(area) = self.single_line_textarea_mut(field) {
311	                        let col = m.column.saturating_sub(inner.x) as usize;
312	                        area.cancel_selection();
313	                        area.move_cursor(CursorMove::Jump(0, col as u16));
314	                        area.start_selection();
315	                    }
316	                    self.selection = None;
317	                    return NoteFormAction::Idle;
318	                }
319	                if let Some(field) = self.field_at(m.row, m.column) {
320	                    self.focus = field;
321	                    self.selection = None;
322	                }
323	                return NoteFormAction::Idle;
324	            }
325	            MouseEventKind::Drag(MouseButton::Left) => {
326	                if let Some(area) = body_area {
327	                    if let Some(pos) = self.body_logical_pos_at(area, m.row, m.column) {
328	                        if let Some((anchor, _)) = self.selection {
329	                            self.selection = Some((anchor, pos));
330	                            self.body
331	                                .move_cursor(CursorMove::Jump(pos.0 as u16, pos.1 as u16));
332	                            return NoteFormAction::Idle;
333	                        }
334	                    }
335	                }
336	                let focused = self.focus;
337	                if let Some(inner) = self.text_field_inner(focused) {
338	                    let target = m.column.saturating_sub(inner.x) as usize;
339	                    if let Some(area) = self.single_line_textarea_mut(focused) {
340	                        select_to_column(area, target);
341	                    }
342	                }
343	            }
344	            MouseEventKind::Up(MouseButton::Left) => {
345	                // Drag-release auto-copies the selection to the system
346	                // clipboard via OSC 52 (see `crate::clip`). The selection
347	                // stays painted so the user can see what got copied;
348	                // a zero-length selection (bare click, no drag) clears
349	                // instead. Body uses the wrap-aware `self.selection`;
350	                // single-line textareas (Title / Tags) keep their own
351	                // `selection_range()`.
352	                if let Some((anchor, tip)) = self.selection {
353	                    if anchor == tip {
354	                        self.selection = None;
355	                    } else {
356	                        let text = selected_text(self.body.lines(), anchor, tip);
357	                        if !text.is_empty() {
358	                            let _ = crate::clip::copy_to_clipboard(&text);
359	                        }
360	                    }
361	                    return NoteFormAction::Idle;
362	                }
363	                let focused = self.focus;
364	                if let Some(area) = self.single_line_textarea_mut(focused) {
365	                    if let Some((anchor, tip)) = area.selection_range() {
366	                        if anchor != tip {
367	                            let text = selected_text(area.lines(), anchor, tip);
368	                            if !text.is_empty() {
369	                                let _ = crate::clip::copy_to_clipboard(&text);
370	                            }
371	                        }
372	                    }
373	                }
374	            }
375	            MouseEventKind::ScrollUp => {
376	                self.body.move_cursor(CursorMove::Up);
377	            }
378	            MouseEventKind::ScrollDown => {
379	                self.body.move_cursor(CursorMove::Down);
380	            }
381	            _ => {}
382	        }
383	        NoteFormAction::Idle
384	    }
