423	    /// Field whose recorded rectangle contains the click, or `None` if the
424	    /// click missed every non-body field.
425	    fn field_at(&self, row: u16, col: u16) -> Option<Field> {
426	        self.field_areas.iter().find_map(|(field, rect)| {
427	            if row >= rect.y
428	                && row < rect.y + rect.height
429	                && col >= rect.x
430	                && col < rect.x + rect.width
431	            {
432	                Some(*field)
433	            } else {
434	                None
435	            }
436	        })
437	    }
438	
439	    fn body_logical_pos_at(&self, area: Rect, row: u16, col: u16) -> Option<(usize, usize)> {
440	        if row < area.y || row >= area.y + area.height {
441	            return None;
442	        }
443	        if col < area.x || col >= area.x + area.width {
444	            return None;
445	        }
446	        let width = area.width as usize;
447	        let visual_row = (row - area.y) as usize + self.body_scroll;
448	        let visual_col = (col - area.x) as usize;
449	        let wrapped = crate::wrap::wrap_for_display(self.body.lines(), self.body.cursor(), width);
450	        Some(wrapped.visual_to_logical(visual_row, visual_col))
451	    }
