485	    /// Push the current title and body back to the daemon. Used by the
486	    /// viewer's debounced autosave.
487	    ///
488	    /// Creates the note first when this is a new form (no id yet) and
489	    /// the title is non-empty; otherwise updates an existing one in place.
490	    /// Diffs against [`Self::baseline`] so an idle field is omitted from
491	    /// `note_update` rather than echoed back stale.
492	    pub fn flush(&mut self) -> Result<()> {
493	        let title = self.current_title();
494	        // Suppress only the new-form case: `note_create` needs a non-
495	        // empty title, and an autosave on a blank-from-the-start form would
496	        // surface that as a spurious error in the message line. Once the
497	        // note exists, the user is allowed to clear its title - the
498	        // update path accepts an empty string. Without this distinction the
499	        // last non-empty intermediate state ("a" while the user is mid-delete
500	        // of "abc") would be the value the daemon and the sidebar see, and
501	        // the next refresh would replay that orphan character back into the
502	        // title field.
503	        if self.id.is_none() && title.is_empty() {
504	            return Ok(());
505	        }
506	        let body = self.current_body();
507	        let tags = self.current_tags();
508	
509	        let client = Client::connect(&self.url)?;
510	        let outcome = (|| -> Result<()> {
511	            let id = match self.id {
512	                Some(id) => id,
513	                None => {
514	                    let created = client.call("note_create", json!({ "title": title }))?;
515	                    let id = created
516	                        .as_u64()
517	                        .ok_or_else(|| anyhow!("daemon returned no note id"))?;
518	                    self.id = Some(id);
519	                    // `note_create` accepts only `title`; the daemon
520	                    // initialises the body to "" and tags to []. Record both
521	                    // in the baseline so the diff below sends whichever body
522	                    // or tags the user typed in the new-note form.
523	                    self.baseline.title = title.clone();
524	                    id
525	                }
526	            };
527	            let mut payload = serde_json::Map::new();
528	            payload.insert("note_id".into(), json!(id));
529	            if title != self.baseline.title {
530	                payload.insert("title".into(), json!(title));
531	            }
532	            if body != self.baseline.body {
533	                payload.insert("body".into(), json!(body));
534	            }
535	            if tags != self.baseline.tags {
536	                payload.insert("tags".into(), json!(tags));
537	            }
538	            // Skip the round-trip when nothing changed - this is the common
539	            // shape of a debounced autosave fired by an unrelated event.
540	            if payload.len() > 1 {
541	                client.call("note_update", Value::Object(payload))?;
542	            }
543	            Ok(())
544	        })();
545	        client.close();
546	        outcome?;
547	        // Refresh the baseline so future flushes diff against what the daemon
548	        // now holds, not what was loaded an edit ago.
549	        self.baseline = Baseline { title, body, tags };
550	        self.dirty = false;
551	        self.dirty_since = None;
552	        self.message = format!("saved note #{}", self.id.unwrap_or(0));
553	        Ok(())
554	    }
555	
556	    /// Pull the daemon's current snapshot and replay it onto the form. Per
557	    /// todo #40 / #65: untouched fields are replaced with the remote value;
558	    /// fields the user is mid-edit on keep their local text and the message
559	    /// line flags the conflict. The [`Baseline`] is always advanced so the
560	    /// next [`Self::flush`] sends only fields still divergent from the
561	    /// remote.
562	    ///
563	    /// Returns `Ok(true)` when anything visible changed and the host should
564	    /// redraw. Not-yet-saved forms (no id) return `Ok(false)` immediately -
565	    /// there is no daemon row to refresh against.
566	    pub fn refresh_from_daemon(&mut self) -> Result<bool> {
567	        let Some(id) = self.id else {
568	            return Ok(false);
569	        };
570	        let client = Client::connect(&self.url)?;
571	        let outcome = client.call("note_get", json!({ "note_id": id }));
572	        client.close();
573	        let pad = outcome?;
574	
575	        let remote = Baseline {
576	            title: pad["title"].as_str().unwrap_or("").to_string(),
577	            body: pad["body"].as_str().unwrap_or("").to_string(),
578	            tags: pad["tags"]
579	                .as_array()
580	                .map(|a| {
581	                    a.iter()
582	                        .filter_map(|v| v.as_str().map(str::to_string))
583	                        .collect()
584	                })
585	                .unwrap_or_default(),
586	        };
587	        let remote_updated = pad["updated_at"].as_str().unwrap_or("").to_string();
588	        let remote_locked_by = pad["locked_by"].as_str().map(str::to_string);
589	        Ok(self.replay_remote(remote, remote_updated, remote_locked_by))
590	    }
591	
592	    /// Apply a daemon snapshot. Pure of MCP - takes the already-loaded values
593	    /// directly - so the replay rules can be unit-tested. See
594	    /// [`Self::refresh_from_daemon`] for the surrounding wire-up.
595	    fn replay_remote(
596	        &mut self,
597	        remote: Baseline,
598	        remote_updated: String,
599	        remote_locked_by: Option<String>,
600	    ) -> bool {
601	        let mut changed = false;
602	        let mut conflicts: Vec<&'static str> = Vec::new();
603	
604	        if remote.title != self.baseline.title {
605	            if self.current_title() != self.baseline.title {
606	                conflicts.push("title");
607	            } else {
608	                self.title = text_area(&remote.title);
609	                changed = true;
610	            }
611	        }
612	        if remote.body != self.baseline.body {
613	            if self.current_body() != self.baseline.body {
614	                conflicts.push("body");
615	            } else {
616	                self.body = text_area(&remote.body);
617	                changed = true;
618	            }
619	        }
620	        if remote.tags != self.baseline.tags {
621	            if self.current_tags() != self.baseline.tags {
622	                conflicts.push("tags");
623	            } else {
624	                self.tags = text_area(&remote.tags.join(", "));
625	                changed = true;
626	            }
627	        }
628	
629	        if self.updated != remote_updated {
630	            self.updated = remote_updated;
631	            changed = true;
632	        }
633	        if self.locked_by != remote_locked_by {
634	            self.locked_by = remote_locked_by;
635	            changed = true;
636	        }
637	
638	        // Advance the baseline unconditionally so a subsequent flush only
639	        // sends fields the user is still mid-edit on.
640	        self.baseline = remote;
641	
642	        if !conflicts.is_empty() {
643	            self.message = format!(
644	                "remote changed {} - your save will overwrite",
645	                conflicts.join(", ")
646	            );
647	            changed = true;
648	        }
649	
650	        changed
651	    }
