661	    /// The tag list parsed from the tags input: comma-split, trim, drop empty.
662	    /// A multi-line paste is normalised to commas first so the result is order-
663	    /// preserving and matches whatever the user sees on screen. Mirrors the
664	    /// todo form's tag parsing.
665	    fn current_tags(&self) -> Vec<String> {
666	        self.tags
667	            .lines()
668	            .join(",")
669	            .split(',')
670	            .map(str::trim)
671	            .filter(|t| !t.is_empty())
672	            .map(String::from)
673	            .collect()
674	    }
