676	    /// Render the form into `area`.
677	    pub fn draw(&mut self, frame: &mut Frame, area: Rect) {
678	        // Rows: title / tags / body / context / message. The pane title (set
679	        // by the Zellij sidebar) already names the note, so no in-form
680	        // header row is needed; locked-by, when set, surfaces in the message
681	        // line at the bottom. Mirrors the todo form's #53 cleanup.
682	        let rows = Layout::vertical([
683	            Constraint::Length(3), // title
684	            Constraint::Length(3), // tags
685	            Constraint::Min(3),    // body
686	            Constraint::Length(1), // context (created/updated)
687	            Constraint::Length(1), // message + help
688	        ])
689	        .split(area);
690	
691	        self.field_areas.clear();
692	        self.text_field_areas.clear();
693	
694	        self.style_field(Field::Title, "Title");
695	        frame.render_widget(&self.title, rows[0]);
696	        self.field_areas.push((Field::Title, rows[0]));
697	        self.text_field_areas
698	            .push((Field::Title, Block::bordered().inner(rows[0])));
699	        self.style_field(Field::Tags, "Tags");
700	        frame.render_widget(&self.tags, rows[1]);
701	        self.field_areas.push((Field::Tags, rows[1]));
702	        self.text_field_areas
703	            .push((Field::Tags, Block::bordered().inner(rows[1])));
704	        self.draw_body(frame, rows[2]);
705	
706	        let context = if !self.created.is_empty() {
707	            format!(" created {}   updated {}", self.created, self.updated)
708	        } else {
709	            String::new()
710	        };
711	        frame.render_widget(
712	            Paragraph::new(context).style(Style::default().fg(Color::DarkGray)),
713	            rows[3],
714	        );
715	
716	        let help = "Tab field  Ctrl-C close";
717	        let lock_prefix = self
718	            .locked_by
719	            .as_deref()
720	            .map(|h| format!("[locked by {h}]   "))
721	            .unwrap_or_default();
722	        let line = if self.message.is_empty() {
723	            format!(" {lock_prefix}{help}")
724	        } else {
725	            format!(" {lock_prefix}{}   |   {help}", self.message)
726	        };
727	        let line_style = if self.locked_by.is_some() {
728	            Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)
729	        } else {
730	            Style::default().fg(Color::Yellow)
731	        };
732	        frame.render_widget(Paragraph::new(line).style(line_style), rows[4]);
733	    }
734	
735	    /// Render the Body field with our soft-wrap renderer. See
736	    /// [`crate::todo_form::TodoForm::draw_body`] for the rationale - the same
737	    /// `tui_textarea` limitation drove this widget here.
738	    fn draw_body(&mut self, frame: &mut Frame, area: Rect) {
739	        let focused = self.focus == Field::Body;
740	        let border = field_border_color(focused);
741	        let block = Block::bordered()
742	            .title("Body")
743	            .border_style(Style::default().fg(border));
744	        let inner = block.inner(area);
745	        frame.render_widget(block, area);
746	
747	        let width = inner.width as usize;
748	        let height = inner.height as usize;
749	        // Same purpose as the matching line in todo_form: feeds the half-page
750	        // step for Ctrl-U / Ctrl-D paging in `body_input`.
751	        self.body_view_height = height;
752	        // Remember the body rectangle so `handle_mouse` can decide whether a
753	        // click hit the body field and, if so, where in it.
754	        self.body_area = Some(inner);
755	        if width == 0 || height == 0 {
756	            return;
757	        }
758	
759	        let cursor = self.body.cursor();
760	        let wrapped = crate::wrap::wrap_for_display(self.body.lines(), cursor, width);
761	        let (cvr, cvc) = wrapped.cursor;
762	
763	        if cvr < self.body_scroll {
764	            self.body_scroll = cvr;
765	        } else if cvr >= self.body_scroll + height {
766	            self.body_scroll = cvr + 1 - height;
767	        }
768	        let max_scroll = wrapped.lines.len().saturating_sub(height);
769	        if self.body_scroll > max_scroll {
770	            self.body_scroll = max_scroll;
771	        }
772	
773	        let selection_ranges: Vec<(usize, usize, usize)> = match self.selection {
774	            Some((a, t)) => wrapped.visual_selection_ranges(a, t),
775	            None => Vec::new(),
776	        };
777	        let visible: Vec<ratatui::text::Line> = wrapped
778	            .lines
779	            .iter()
780	            .enumerate()
781	            .skip(self.body_scroll)
782	            .take(height)
783	            .map(|(vrow, l)| {
784	                if let Some(&(_, from, to)) = selection_ranges.iter().find(|(r, _, _)| *r == vrow) {
785	                    highlight_line(l, from, to)
786	                } else {
787	                    ratatui::text::Line::from(l.clone())
788	                }
789	            })
790	            .collect();
791	        frame.render_widget(Paragraph::new(visible), inner);
792	
793	        if focused && cvr >= self.body_scroll && cvr < self.body_scroll + height && cvc < width {
794	            let cy = inner.y + (cvr - self.body_scroll) as u16;
795	            let cx = inner.x + cvc as u16;
796	            frame.set_cursor_position((cx, cy));
797	        }
798	    }
799	
800	    /// Set a text field's border and cursor styling for the current focus.
801	    /// Mirrors [`crate::todo_form`]'s helper of the same name. Body is
802	    /// excluded - it has its own wrapped render in [`Self::draw_body`].
803	    fn style_field(&mut self, field: Field, label: &'static str) {
804	        let focused = self.focus == field;
805	        let area = match field {
806	            Field::Title => &mut self.title,
807	            Field::Tags => &mut self.tags,
808	            Field::Body => return,
809	        };
810	        let border = field_border_color(focused);
811	        area.set_block(
812	            Block::bordered()
813	                .title(label)
814	                .border_style(Style::default().fg(border)),
815	        );
816	        area.set_cursor_style(if focused {
817	            Style::default().add_modifier(Modifier::REVERSED)
818	        } else {
819	            Style::default()
820	        });
821	    }
822	}
823	
