177	/// (`agent_tools`) and an instance layer (`processes`) (todo #27).
178	///
179	/// A V5 roster row was both a config (name, command, cwd) and the implicit
180	/// single instance of that config; liveness was derived from Zellij pane state,
181	/// never stored. V6 mirrors Solo's two-layer model: `agent_tools` holds the
182	/// durable configurations, `processes` holds per-project instances and carries
183	/// a nullable FK back to its source tool plus nullable lifecycle columns
184	/// (`pid`, `status`, `agent_state`, `last_seen`) so a follow-up that owns
185	/// process spawn can populate them without another migration.
186	///
187	/// Both new tables keep drawing ids from the unified `projects.next_id`
188	/// counter introduced by V5, so a `#N` reference still resolves to exactly one
189	/// row across todos, scratchpads, agent_tools, and processes.
190	///
191	/// Migration of existing rows: `kind='agent'` becomes an `agent_tools` row
192	/// (configuration), and `kind='command'` / `kind='terminal'` become
193	/// `processes` rows (instances - the only thing the pre-split roster ever was
194	/// for those kinds). Ids are preserved verbatim since both new tables share
195	/// the same `next_id` sequence the originals were drawn from.
196	fn apply_v6(conn: &Connection) -> Result<(), rusqlite::Error> {
197	    conn.execute_batch(
198	        "CREATE TABLE agent_tools (
199	             project_id   INTEGER NOT NULL REFERENCES projects(id),
200	             id           INTEGER NOT NULL,
201	             name         TEXT    NOT NULL,
202	             display_name TEXT    NOT NULL DEFAULT '',
203	             command      TEXT    NOT NULL DEFAULT '',
204	             cwd          TEXT    NOT NULL DEFAULT '',
205	             tool_type    TEXT    NOT NULL DEFAULT 'agent',
206	             enabled      INTEGER NOT NULL DEFAULT 1,
207	             position     INTEGER NOT NULL DEFAULT 0,
208	             created_at   TEXT    NOT NULL,
209	             PRIMARY KEY (project_id, id)
210	         );
211	         CREATE TABLE processes (
212	             project_id    INTEGER NOT NULL REFERENCES projects(id),
213	             id            INTEGER NOT NULL,
214	             kind          TEXT    NOT NULL CHECK (kind IN ('agent','command','terminal')),
215	             name          TEXT    NOT NULL DEFAULT '',
216	             display_name  TEXT    NOT NULL DEFAULT '',
217	             command       TEXT    NOT NULL DEFAULT '',
218	             cwd           TEXT    NOT NULL DEFAULT '',
219	             position      INTEGER NOT NULL DEFAULT 0,
220	             agent_tool_id INTEGER,
221	             pid           INTEGER,
222	             status        TEXT,
223	             agent_state   TEXT,
224	             last_seen     TEXT,
225	             created_at    TEXT    NOT NULL,
226	             PRIMARY KEY (project_id, id)
227	         );
228	         INSERT INTO agent_tools
229	             (project_id, id, name, display_name, command, cwd, tool_type, enabled, position, created_at)
230	             SELECT project_id, id, name, display_name, command, cwd, 'agent', 1, position, created_at
231	               FROM roster WHERE kind = 'agent';
232	         INSERT INTO processes
233	             (project_id, id, kind, name, display_name, command, cwd, position, created_at)
234	             SELECT project_id, id, kind, name, display_name, command, cwd, position, created_at
235	               FROM roster WHERE kind IN ('command','terminal');
236	         DROP TABLE roster;",
237	    )
